data.arguments:
{"command":"$ErrorActionPreference='Stop'
$root='/workspace/just-thinking'
$files = Get-ChildItem $root -Recurse -File -Force -ErrorAction SilentlyContinue
"total files: $($files.Count)"
"total MB: " + [math]::Round(($files | Measure-Object Length -Sum).Sum/1MB,1)
# 按一级目录聚合
$files | ForEach-Object {
  $rel = $_.FullName.Substring($root.Length+1)
  $top = if($rel -match '\\'){ ($rel -split '\\')[0] } else { '(root)' }
  [pscustomobject]@{Top=$top; MB=$_.Length/1MB; Age=((Get-Date)-$_.LastWriteTime).TotalDays}
} | Group-Object Top | ForEach-Object {
  [pscustomobject]@{Dir=$_.Name; Files=$_.Count; MB=[math]::Round(($_.Group|Measure-Object MB -Sum).Sum,1); AvgAgeDays=[math]::Round(($_.Group|Measure-Object Age -Average).Average,0)}
} | Sort-Object MB -Descending | Format-Table -AutoSize | Out-String -Width 160","description":"Aggregate workspace sizes by top dir","timeoutMs":180000}

